public class LibraryMemberV2 { private static int totalMembersEnrolled = 0; public final String memberNumber; private int borrowLimit; private int booksBorrowed = 0; private String lastGenre; public LibraryMemberV2(int borrowLimit) { totalMembersEnrolled++; this.memberNumber = "LIB-" + (100 + totalMembersEnrolled); this.borrowLimit = borrowLimit; } public void borrowBook() { if (booksBorrowed < borrowLimit) booksBorrowed++; } public void borrowBook(String genre) { this.lastGenre = genre; this.borrowBook(); } public int getBooksBorrowed() { return booksBorrowed; } public static boolean isValidRenewalCode(String code) { if (code == null || code.length() != 4) return false; return code.charAt(0) == 'R' && Character.isDigit(code.charAt(1)) && Character.isDigit(code.charAt(2)) && Character.isUpperCase(code.charAt(3)); } public static int getMembersEnrolled() { return totalMembersEnrolled; } public static String processNightlyAudit(LibraryMemberV2[] members) { int processed = 0, skipped = 0, faculty = 0, regular = 0; for (LibraryMemberV2 m : members) { if (m == null) { skipped++; continue; } processed++; if (m instanceof FacultyMemberV2) faculty++; else regular++; } return processed + " processed | " + skipped + " null skipped | " + faculty + " faculty | " + regular + " regular"; } public static void main(String[] args) { LibraryMemberV2 m1 = new LibraryMemberV2(3); System.out.println("Member ID: " + m1.memberNumber); System.out.println("Total Enrolled: " + getMembersEnrolled()); System.out.println("isValidRenewalCode(\"R12A\"): " + isValidRenewalCode("R12A")); System.out.println("isValidRenewalCode(\"R1A\"): " + isValidRenewalCode("R1A")); System.out.println("isValidRenewalCode(\"X12A\"): " + isValidRenewalCode("X12A")); m1.borrowBook(); m1.borrowBook("Fiction"); System.out.println("Books Borrowed: " + m1.getBooksBorrowed()); LibraryMemberV2[] batch = {new FacultyMemberV2(5, "Physics"), null, new LibraryMemberV2(3)}; System.out.println(processNightlyAudit(batch)); } }
class FacultyMemberV2 extends LibraryMemberV2 { private String department; public FacultyMemberV2(int borrowLimit, String department) { super(borrowLimit); this.department = department; } public String getDepartment() { return department; } }